}

// --- Brick collision (#1) --------------------------------------------------

// Penetration of the ball's box into the brick, per axis, in pixels.
function penetration(ball, brick) {
  const dx = Math.min(ball.x + ball.r, brick.x + brick.w) - Math.max(ball.x - ball.r, brick.x);
  const dy = Math.min(ball.y + ball.r, brick.y + brick.h) - Math.max(ball.y - ball.r, brick.y);
  return { dx, dy };
}

// One bounce against one brick.
//  - per face: the axis with the smaller penetration is the face that was hit;
//    flip only that component and leave the other exactly as it was;
//  - corner: equal penetrations mean a diagonal hit, both components flip;
//  - push out: reposition the ball outside the brick rectangle on the flipped
//    axis, otherwise it still overlaps on the next frame and re-flips forever
//    (sticky bounce). The push goes toward the nearer edge, which is also the
//    cheaper exit.
function resolveBrick(state, brick) {
  const { ball } = state;
  brick.alive = false;
  state.combo += 1;
  state.score += scoreForBrick(brick, state.combo);

  const { dx, dy } = penetration(ball, brick);

  const pushX = () => {
    ball.x = ball.x < brick.x + brick.w / 2 ? brick.x - ball.r : brick.x + brick.w + ball.r;
  };
  const pushY = () => {
    ball.y = ball.y < brick.y + brick.h / 2 ? brick.y - ball.r : brick.y + brick.h + ball.r;
  };

  if (dx < dy) {
    ball.vx = -ball.vx;
    pushX();
  } else if (dy < dx) {
    ball.vy = -ball.vy;
    pushY();
  } else {
    ball.vx = -ball.vx;
    ball.vy = -ball.vy;
    pushX();
    pushY();
  }
}

// Swept test: does the ball cross the brick while travelling from (px, py) to
// (nx, ny)? The ball is a circle, so the brick is grown by the radius and the
// segment between the two centers is tested against that box (slab method).
// Returns the impact point, or null when there is no crossing. A ball that was
// already overlapping the grown box at the start is NOT a crossing: the
// discrete test in bounceOffBricks() handles that case.
function sweptHit(ball, brick, px, py, nx, ny) {
  const dx = nx - px;
  const dy = ny - py;
  if (dx === 0 && dy === 0) return null;

  let t0 = 0;
  let t1 = 1;
  const slab = (p, d, lo, hi) => {
    if (d === 0) return p >= lo && p <= hi;
    let a = (lo - p) / d;
    let b = (hi - p) / d;
    if (a > b) {
      const t = a;
      a = b;
      b = t;
    }
    if (a > t0) t0 = a;
    if (b < t1) t1 = b;
    return t0 <= t1;
  };

  if (!slab(px, dx, brick.x - ball.r, brick.x + brick.w + ball.r)) return null;
  if (!slab(py, dy, brick.y - ball.r, brick.y + brick.h + ball.r)) return null;
  if (t0 <= 0) return null; // already overlapping at the start, not a crossing

  return { x: px + dx * t0, y: py + dy * t0 };
}

// Resolves every live brick the ball touches this step.
//  - discrete overlap (the ball is already inside the brick): bounce + push out;
//  - otherwise a swept test against the travelled segment catches a fast ball
//    that would jump over the brick in a single frame (tunnelling).
// The push-out guarantees each bounce applies exactly once even when the grid
// gap (8 px < ball diameter 14 px) makes the ball overlap two bricks in the
// same pass: after the first bounce the ball no longer overlaps the second,
// so `vy = -vy` is never applied twice (which would cancel out).
function bounceOffBricks(state, px, py) {
  const { ball, bricks } = state;

  for (const brick of bricks) {
    if (!brick.alive) continue;

    if (collides(ball, brick)) {
      resolveBrick(state, brick);
      continue;
    }

    const hit = sweptHit(ball, brick, px, py, ball.x, ball.y);
    if (hit) {
      ball.x = hit.x;
      ball.y = hit.y;
      resolveBrick(state, brick);
    }
  }
}

// --- Rendering (DOM) -------------------------------------------------------

// Main render loop. Pure drawing: brick collision (bounce + push-out + score)
// now lives in step() → bounceOffBricks(), so rendering cannot double-bounce
// the ball nor run game logic inside the draw pass (see #1, #2).
export function frame(ctx, state) {
  // Background
  ctx.fillStyle = palette.background;
  ctx.fillRect(0, 0, WIDTH, HEIGHT);

  // Bricks: drawing only.
  for (const brick of state.bricks) {
    if (!brick.alive) continue;

    ctx.fillStyle = brickColor(brick.row);
    ctx.fillRect(brick.x, brick.y, brick.w, brick.h);
  }

